import{_ as t,o as e,c as r,a2 as o}from"./chunks/framework.BZO4qERu.js";const m=JSON.parse('{"title":"Настройка канала WeChat","description":"","frontmatter":{},"headers":[],"relativePath":"ru/integrations/channels/weixin.md","filePath":"ru/integrations/channels/weixin.md","lastUpdated":1792323081000}'),i={name:"ru/integrations/channels/weixin.md"};function h(n,a,l,s,d,c){return e(),r("div",null,[...a[0]||(a[0]=[o('<h1 id="настроика-канала-wechat" tabindex="-1">Настройка канала WeChat <a class="header-anchor" href="#настроика-канала-wechat" aria-label="Permalink to &quot;Настройка канала WeChat&quot;">​</a></h1><p>Подключите своего Bot в Memoh к личной переписке WeChat: вся настройка — это вход по QR-коду, без ручного ввода токенов и API-ключей.</p><div class="warning custom-block"><p class="custom-block-title">Ограничения</p><ul><li>Только личные чаты.</li><li>Вывод — только обычный текст; Markdown не отображается.</li><li>Текстовые сообщения разбиваются на части не более 4000 символов.</li><li>Ответы доставляются целыми сообщениями; потоковый вывод не поддерживается.</li></ul></div><h2 id="предварительные-условия" tabindex="-1">Предварительные условия <a class="header-anchor" href="#предварительные-условия" aria-label="Permalink to &quot;Предварительные условия&quot;">​</a></h2><ul><li>WeChat на вашем телефоне со входом в аккаунт, которым будет пользоваться Bot, — вход подтверждается сканированием QR-кода.</li></ul><h2 id="шаги" tabindex="-1">Шаги <a class="header-anchor" href="#шаги" aria-label="Permalink to &quot;Шаги&quot;">​</a></h2><h3 id="_1-добавьте-канал-wechat-в-memoh" tabindex="-1">1. Добавьте канал WeChat в Memoh <a class="header-anchor" href="#_1-добавьте-канал-wechat-в-memoh" aria-label="Permalink to &quot;1. Добавьте канал WeChat в Memoh&quot;">​</a></h3><p>В Memoh откройте вкладку <strong>Platforms</strong> нужного Bot, нажмите <strong>Add Channel</strong> и выберите <strong>WeChat</strong>.</p><h3 id="_2-отсканируите-qr-код" tabindex="-1">2. Отсканируйте QR-код <a class="header-anchor" href="#_2-отсканируите-qr-код" aria-label="Permalink to &quot;2. Отсканируйте QR-код&quot;">​</a></h3><p>В Memoh:</p><ol><li>Нажмите <strong>Start QR Login</strong>. Memoh получит QR-код с платформы WeChat.</li><li>Откройте WeChat на телефоне и отсканируйте показанный QR-код.</li><li>Подтвердите вход на телефоне, когда появится запрос.</li></ol><p>После подтверждения Memoh автоматически сохранит учётные данные, и канал будет включён.</p><h2 id="учетные-данные" tabindex="-1">Учётные данные <a class="header-anchor" href="#учетные-данные" aria-label="Permalink to &quot;Учётные данные&quot;">​</a></h2><p>Вход по QR-коду сохраняет учётные данные сессии автоматически — заполнять поля не нужно. Доступна одна необязательная настройка:</p><table tabindex="0"><thead><tr><th>Поле</th><th>Обязательное</th><th>Описание</th></tr></thead><tbody><tr><td><strong>Enable Typing</strong></td><td>Нет</td><td>Показывает индикатор набора текста, пока Bot готовит ответ.</td></tr></tbody></table><h2 id="проверка" tabindex="-1">Проверка <a class="header-anchor" href="#проверка" aria-label="Permalink to &quot;Проверка&quot;">​</a></h2><p>После успешного входа по QR-коду канал включается автоматически. Отправьте Bot <code>/help</code> в личном чате WeChat; Bot ответит списком команд — это подтверждает, что канал работает.</p><h2 id="отключение-и-смена-учетных-данных" tabindex="-1">Отключение и смена учётных данных <a class="header-anchor" href="#отключение-и-смена-учетных-данных" aria-label="Permalink to &quot;Отключение и смена учётных данных&quot;">​</a></h2><p>Отключить или удалить канал можно в любой момент на вкладке <strong>Platforms</strong> нужного Bot. Чтобы войти заново, нажмите <strong>Start QR Login</strong> и повторите сканирование QR-кода.</p><h2 id="faq" tabindex="-1">Частые вопросы <a class="header-anchor" href="#faq" aria-label="Permalink to &quot;Частые вопросы {#faq}&quot;">​</a></h2><h3 id="qr-expired" tabindex="-1">QR-код истёк раньше, чем я его отсканировал <a class="header-anchor" href="#qr-expired" aria-label="Permalink to &quot;QR-код истёк раньше, чем я его отсканировал {#qr-expired}&quot;">​</a></h3><p>QR-код действует ограниченное время. Нажмите <strong>Start QR Login</strong> ещё раз, чтобы получить новый.</p>',22)])])}const u=t(i,[["render",h]]);export{m as __pageData,u as default};
